```cpp
#include <string>
#include <iostream>
#include <sstream>
#include <boost/algorithm/string.hpp>  // für Boost::algorithm::replace_all

std::string convertMarkdownToHtml(const std::string& markdown) {
    std::stringstream htmlStream;

    htmlStream << "<div class='markdown'>";

    // Header 1
    boost::algorithm::replace_all(markdown, "# ", "<h1>");
    boost::algorithm::replace_all(markdown, "## ", "<h2>");
    boost::algorithm::replace_all(markdown, "### ", "<h3>");
    boost::algorithm::replace_all(markdown, "#### ", "<h4>");
    boost::algorithm::replace_all(markdown, "##### ", "<h5>");
    boost::algorithm::replace_all(markdown, "###### ", "<h6>");
    htmlStream << markdown << "</div>";

    // Emphasis
    boost::algorithm::replace_all(markdown, "*", "<em>");
    boost::algorithm::replace_all(markdown, "_", "<em>");
    boost::algorithm::replace_all(markdown, "**", "<strong>");
    boost::algorithm::replace_all(markdown, "__", "<strong>");
    boost::algorithm::replace_all(markdown, "`", "<code>");
    boost::algorithm::replace_all(markdown, "``", "<pre><code>");
    boost::algorithm::replace_all(markdown, "```", "</code></pre>");
    htmlStream << markdown;

    // Links
    boost::algorithm::replace_all(markdown, "[", "<a href='");
    boost::algorithm::replace_all(markdown, "]", "'>");
    boost::algorithm::replace_all(markdown, "](http)", ">$1");

    // Images
    boost::algorithm::replace_all(markdown, "![(alt text)]\(url)", "<img src=\"$2\" alt=\"$1\">");

    htmlStream << "</div>";

    std::string html = htmlStream.str();
    return html;
}

int main() {
    std::string markdown = "## Header 1\n"
                           "This is a **bold** and *italic* text.\n"
                           "Here's a [link](https://example.com) and an image: ! [Alt text](https://example.com/image.jpg)\n"
                           "And some code: ``c++ code``";

    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

