using namespace std;

int main() {
    string wordToCount; // Wort, das gezählt werden soll
    string inputFileName; // Name der Eingabedatei

    // Wort und Dateiname von der Benutzereingabe lesen
    cout << "Geben Sie das zu zählende Wort ein: ";
    cin >> wordToCount;

    cout << "Geben Sie den Dateinamen ein: ";
