    ifstream inputFile(inputFileName);
    if (!inputFile) {
        cerr << "Fehler: Datei nicht gefunden oder nicht lesbar!" << endl;
        return 1;
    }

    string line; // Variabler für Zeilenlesung
    int wordCount = 0; // Variabler für Wortzähler

    // Zeilen lesen und Wort zählen
    while (getline(inputFile, line)) {
        // Zeile in einzelne Wörter aufspalten
        size_t pos = 0;
        string token;
        while ((pos = line.find(" ")) != string::npos) {
            token = line.substr(pos, pos + 1 - wordCount);
            // Wenn das aktuelle Wort mit dem gesuchten Wort übereinstimmt, zählen
            if (token == wordToCount) {
                wordCount++;
            }
            line.erase(pos, pos + 1);
        }
        // Letztes Wort zählen
        if (line == wordToCount) {
            wordCount++;
        }
    }

    // Ergebnis ausgeben
    cout << "Das Wort '" << wordToCount << "' kommt " << wordCount << " mal in der Datei " << inputFileName << " vor." << endl;

    inputFile.close();

    return 0;
}
